// 收藏一个服务（幂等）。
func (q *Queries) UpsertServiceStar(ctx context.Context, arg UpsertServiceStarParams) (int64, error) {
	result, err := q.db.Exec(ctx, upsertServiceStar, arg.TenantID, arg.ServiceID, arg.UserID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const upsertViewOverride = `-- name: UpsertViewOverride :one
INSERT INTO view_overrides (tenant_id, view_id, enabled, ord, default_options, revision)
VALUES ($1, $2, $3, $4, $5::jsonb, 1)
ON CONFLICT (tenant_id, view_id) DO UPDATE SET
  enabled = EXCLUDED.enabled,
  ord = EXCLUDED.ord,
  default_options = EXCLUDED.default_options,
  revision = view_overrides.revision + 1,
  updated_at = now()
RETURNING tenant_id, view_id, enabled, ord, default_options, revision, updated_at
`

// UpsertViewOverrideParams 包含 UpsertViewOverride 查询的强类型参数。
type UpsertViewOverrideParams struct {
	// TenantID 是提供给 UpsertViewOverride 查询的 TenantID 值。
	TenantID uuid.UUID `json:"tenant_id"`
	// ViewID 是提供给 UpsertViewOverride 查询的 ViewID 值。
	ViewID string `json:"view_id"`
	// Enabled 是提供给 UpsertViewOverride 查询的 Enabled 值。
	Enabled bool `json:"enabled"`
	// Ord 是提供给 UpsertViewOverride 查询的 Ord 值。
	Ord int32 `json:"ord"`
	// DefaultOptions 是提供给 UpsertViewOverride 查询的 DefaultOptions 值。
	DefaultOptions []byte `json:"default_options"`
}

// UpsertViewOverride 执行生成的 UpsertViewOverride 数据库查询。
// 幂等设置一条视图覆盖（创建或替换并递增 revision）。
func (q *Queries) UpsertViewOverride(ctx context.Context, arg UpsertViewOverrideParams) (ViewOverride, error) {
	row := q.db.QueryRow(ctx, upsertViewOverride,
		arg.TenantID,
		arg.ViewID,
		arg.Enabled,
		arg.Ord,
		arg.DefaultOptions,
	)
	var i ViewOverride
	err := row.Scan(
		&i.TenantID,
		&i.ViewID,
		&i.Enabled,
		&i.Ord,
		&i.DefaultOptions,
		&i.Revision,
		&i.UpdatedAt,
	)
	return i, err
}
